// Plus Two entrance chemistry bank: General principles of metallurgy (Class 12). Original fibub questions.
// Data used: Fe 56, Al 27, Cu 63.5, Zn 65, Pb 207, Ca 40, Mg 24, Si 28, Cr 52, C 12, S 32, O 16; 1 F = 96500 C; molar volume 22.4 L at STP.
// Ellingham: dG = dH - T dS; the line for a metal turning into its oxide slopes up because gas is used up (dS negative).
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0, _c = 0;
const nid = () => `mt-${String(++_c).padStart(3, '0')}`;
const EXB = { 1: ['keam', 'cusat', 'comedk', 'jee-main'], 2: ['keam', 'cusat', 'comedk', 'jee-main'], 3: ['jee-main', 'comedk'], 4: ['jee-main', 'jee-adv'], 5: ['jee-adv'] };
const EX = (l, t = 'mcq') => (t === 'mcq' && l <= 3 ? [...EXB[l], 'cuet'] : EXB[l]);
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const mk = (level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id: nid(), type: 'mcq', level, format: 'single', exams: EX(level), sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (level, sub, q, answer, tol, unit, sol, trap, calc) => ({ id: nid(), type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX(level, 'nat'), sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) });
const msq = (level, sub, q, options, answer, sol, trap) => ({ id: nid(), type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (level, sub, A, R, answer, sol, trap) => ({ id: nid(), type: 'mcq', level, format: 'assertion', exams: EX(level), sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (level, sub, s1, s2, answer, sol, trap) => ({ id: nid(), type: 'mcq', level, format: 'statements', exams: EX(level), sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const cnt = (level, sub, q, options, answer, sol, trap) => ({ id: nid(), type: 'mcq', level, format: 'statements', exams: EX(level), sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const mat = (level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (level, sub, group, q, answer, tol, unit, sol, trap, calc) => ({ ...nat(level, sub, q, answer, tol, unit, sol, trap, calc), format: 'passage', group });
/** rows: [q, right, [3 wrongs], sol, trap?] */
const T = (level, sub, rows) => rows.map(([q, r, w, s, t]) => mk(level, sub, q, r, w, s, t));
const gx = (id, level, type, sub, make, verify) => ({ id, type, level, exams: EX(level, type), sub, make, ...(verify ? { verify } : {}) });

const GRP = {
  m1: { title: 'Match the ore with the metal it is mainly used to extract', list1: ['A. Cassiterite', 'B. Cinnabar', 'C. Siderite', 'D. Argentite'], list2: ['p. Iron', 'q. Silver', 'r. Tin', 's. Mercury'] },
  m2: { title: 'Match the refining method with the metal it is used for', list1: ['A. Mond process', 'B. van Arkel method', 'C. Zone refining', 'D. Poling'], list2: ['p. Germanium for semiconductors', 'q. Zirconium', 'r. Blister copper', 's. Nickel'] },
  m3: { title: 'Match the step with the equation or reagent', list1: ['A. Leaching of bauxite', 'B. Roasting of zinc blende', 'C. Calcination of limestone', 'D. Recovery of silver from its cyanide complex'], list2: ['p. CaCO<sub>3</sub> &rarr; CaO + CO<sub>2</sub>', 'q. Zinc dust', 'r. Hot concentrated NaOH solution', 's. 2ZnS + 3O<sub>2</sub> &rarr; 2ZnO + 2SO<sub>2</sub>'] },
  m4: { title: 'Match the part of the blast furnace with what happens there', list1: ['A. Top zone, about 500&ndash;800 K', 'B. Middle zone, about 900&ndash;1500 K', 'C. Slag zone', 'D. Bottom zone, near the tuyeres'], list2: ['p. Coke burns to give CO<sub>2</sub> and heat', 'q. CaO + SiO<sub>2</sub> &rarr; CaSiO<sub>3</sub>', 'r. Fe<sub>2</sub>O<sub>3</sub> is reduced to Fe<sub>3</sub>O<sub>4</sub> by CO', 's. FeO is reduced to Fe by CO; limestone decomposes'] },
  p1: { title: 'Reading an Ellingham diagram', passage: '<p>For a certain furnace, the standard free energy change per mole of O<sub>2</sub> for forming oxides is given by straight lines in kJ (T in kelvin):</p><p>Oxide of metal M: &Delta;G&deg; = &minus;760 + 0.20 T. &nbsp; Formation of CO from carbon (2C + O<sub>2</sub> &rarr; 2CO): &Delta;G&deg; = &minus;220 &minus; 0.20 T. &nbsp; Oxide of metal N: &Delta;G&deg; = &minus;1050 + 0.18 T.</p>' },
  p2: { title: 'Extraction of copper from copper pyrites', passage: '<p>Copper pyrites, CuFeS<sub>2</sub>, is concentrated by froth flotation. The concentrate is roasted in air, which turns part of the iron sulphide into FeO and gives SO<sub>2</sub>. The roasted mass is heated with silica in a reverberatory furnace, so that the iron is removed as a slag and a molten mixture called matte is left. The matte is poured into a converter and air is blown through it with silica. The product is solid copper with a blistered surface.</p>' },
  p3: { title: 'The Hall&ndash;H&eacute;roult cell', passage: '<p>Pure alumina is dissolved in molten cryolite with a little fluorspar and electrolysed between graphite electrodes at about 1200 K. The steel tank is lined with graphite and acts as the cathode. The anodes are graphite blocks that must be replaced from time to time. The overall change is 2Al<sub>2</sub>O<sub>3</sub> + 3C &rarr; 4Al + 3CO<sub>2</sub>. Take Al = 27, C = 12, O = 16, 1 F = 96500 C.</p>' },
};

const H1 = [
  ...T(1, 'occurrence', [
    [`A naturally occurring substance from which a metal can be extracted profitably is called a(n)`, `ore`, [`gangue`, `flux`, `slag`], `<p>A <b>mineral</b> is any natural compound of a metal; an <b>ore</b> is a mineral from which the metal can be got easily and cheaply.</p>`, `All ores are minerals, but not all minerals are ores.`],
    [`The earthy impurities present in an ore are called`, `gangue`, [`slag`, `matte`, `flux`], `<p>Gangue (matrix) is the unwanted rock and sand that comes with the ore. Slag is what forms when a flux joins the gangue in the furnace.</p>`],
    [`The formula of haematite is`, `Fe<sub>2</sub>O<sub>3</sub>`, [`Fe<sub>3</sub>O<sub>4</sub>`, `FeCO<sub>3</sub>`, `FeS<sub>2</sub>`], `<p>Haematite is the red oxide Fe<sub>2</sub>O<sub>3</sub>. Magnetite is Fe<sub>3</sub>O<sub>4</sub>, siderite is FeCO<sub>3</sub> and iron pyrites is FeS<sub>2</sub>.</p>`],
    [`The chief ore of aluminium is`, `bauxite, Al<sub>2</sub>O<sub>3</sub>&middot;xH<sub>2</sub>O`, [`cryolite, Na<sub>3</sub>AlF<sub>6</sub>`, `kaolin used as an ore of iron`, `corundum used mainly as an abrasive and not mined as the main ore`], `<p>Bauxite is the main ore. Cryolite is not an ore for the metal; it is used as the solvent in the electrolysis. Corundum is crystalline Al<sub>2</sub>O<sub>3</sub>, a gemstone and abrasive.</p>`],
    [`Zinc blende has the formula`, `ZnS`, [`ZnCO<sub>3</sub>`, `ZnO`, `ZnSO<sub>4</sub>`], `<p>Zinc blende (sphalerite) is zinc sulphide. Calamine is ZnCO<sub>3</sub> and zincite is ZnO.</p>`],
    [`Copper pyrites has the formula`, `CuFeS<sub>2</sub>`, [`Cu<sub>2</sub>S`, `Cu<sub>2</sub>O`, `CuCO<sub>3</sub>&middot;Cu(OH)<sub>2</sub>`], `<p>Copper pyrites (chalcopyrite) is CuFeS<sub>2</sub>. Copper glance is Cu<sub>2</sub>S, cuprite is Cu<sub>2</sub>O and malachite is CuCO<sub>3</sub>&middot;Cu(OH)<sub>2</sub>.</p>`],
    [`Galena is the ore of`, `lead, PbS`, [`silver, Ag<sub>2</sub>S`, `zinc, ZnS`, `mercury, HgS`], `<p>Galena is lead sulphide, PbS.</p>`],
    [`Which of these metals is found in the native (free) state in nature?`, `Gold`, [`Sodium`, `Aluminium`, `Zinc`], `<p>Unreactive metals such as gold, platinum and sometimes silver and copper occur free. Sodium, aluminium and zinc are reactive and occur as compounds.</p>`],
  ]),
  ...T(1, 'extraction steps', [
    [`Heating an ore in a limited supply of air or none, below its melting point, is called`, `calcination`, [`roasting`, `smelting`, `leaching`], `<p>Calcination removes water and CO<sub>2</sub> from hydrated oxides and carbonates. Roasting is done in excess air.</p>`],
    [`Roasting is mainly used for`, `sulphide ores, converting them to oxides`, [`carbonate ores, giving CO<sub>2</sub>`, `oxide ores of aluminium`, `purifying native gold`], `<p>In excess air a sulphide is oxidised: 2ZnS + 3O<sub>2</sub> &rarr; 2ZnO + 2SO<sub>2</sub>.</p>`],
    [`Froth flotation is used to concentrate`, `sulphide ores`, [`carbonate ores`, `haematite`, `native gold`], `<p>Sulphide ore particles are wetted by oil and carried up in the froth. Oxide ores are usually concentrated by other methods.</p>`],
    [`A substance added to remove the gangue as an easily fusible material is a`, `flux`, [`collector`, `depressant`, `frother`], `<p>A flux combines with the gangue to form a slag that melts and runs off.</p>`],
    [`Blast furnace iron which contains about 4% carbon is`, `pig iron`, [`wrought iron`, `stainless steel`, `mild steel`], `<p>Pig iron has about 4% carbon with some Si, S, P and Mn. Wrought iron has the least (0.1 to 0.25%).</p>`],
    [`In the Hall&ndash;H&eacute;roult process the anode is made of`, `graphite (carbon)`, [`platinum`, `aluminium`, `copper`], `<p>The anodes are graphite blocks. They are slowly burnt away by the oxygen formed and have to be renewed.</p>`],
    [`Impure copper is refined by`, `electrolysis`, [`froth flotation`, `leaching with NaOH`, `zone refining`], `<p>Impure copper is the anode, pure copper the cathode, and the electrolyte is acidified copper sulphate.</p>`],
    [`Cryolite has the formula`, `Na<sub>3</sub>AlF<sub>6</sub>`, [`Na<sub>2</sub>AlF<sub>5</sub>`, `AlF<sub>3</sub>`, `Na<sub>3</sub>AlCl<sub>6</sub>`], `<p>Cryolite is sodium hexafluoroaluminate(III).</p>`],
    [`Zone refining is used to get very pure`, `germanium`, [`iron`, `sodium`, `aluminium oxide`], `<p>It is used for semiconductors such as Ge, Si and Ga, where a part in 10<sup>9</sup> of impurity matters.</p>`],
    [`The slag in the blast furnace is mainly`, `calcium silicate, CaSiO<sub>3</sub>`, [`iron silicate, FeSiO<sub>3</sub>`, `calcium carbonate`, `calcium sulphate`], `<p>Limestone gives CaO, which is a basic flux, and it joins the acidic gangue SiO<sub>2</sub>: CaO + SiO<sub>2</sub> &rarr; CaSiO<sub>3</sub>.</p>`],
  ]),
];

const H2 = [
  ...T(2, 'concentration', [
    [`In froth flotation, pine oil acts mainly as a`, `frother, and it also helps wet the sulphide particles`, [`depressant for lead sulphide`, `flux for silica`, `reducing agent`], `<p>Pine oil and cresols are frothers that make a stable froth. Collectors such as xanthates make the ore wettable by oil. The ore particles rise with the bubbles, while gangue wetted by water sinks.</p>`],
    [`In a mixture of ZnS and PbS, sodium cyanide is added in froth flotation so that`, `ZnS is kept from rising, and PbS comes up with the froth`, [`PbS is kept from rising, and ZnS comes up with the froth`, `both sulphides rise together`, `both sulphides stay down`], `<p>NaCN acts as a depressant. It forms a soluble complex, Na<sub>2</sub>[Zn(CN)<sub>4</sub>], on the surface of ZnS, so ZnS stops rising, while PbS is left to float.</p>`, `The depressant selects which sulphide stays down.`],
    [`The concentration of bauxite from its ore by Baeyer's (Bayer's) leaching uses`, `hot concentrated NaOH solution, which dissolves Al<sub>2</sub>O<sub>3</sub> as sodium aluminate and leaves Fe<sub>2</sub>O<sub>3</sub> and TiO<sub>2</sub>`, [`dilute HCl, which dissolves Fe<sub>2</sub>O<sub>3</sub> and leaves Al<sub>2</sub>O<sub>3</sub>`, `cold dilute H<sub>2</sub>SO<sub>4</sub>`, `a magnet to remove iron`], `<p>Al<sub>2</sub>O<sub>3</sub> is amphoteric. It dissolves in hot NaOH as Na[Al(OH)<sub>4</sub>]. Iron oxide and titania, which are basic or inert, remain as red mud.</p>`],
    [`Which of these is concentrated by magnetic separation?`, `Wolframite (magnetic) mixed with non-magnetic cassiterite`, [`Zinc blende`, `Copper glance`, `Galena`], `<p>The magnetic ore, or magnetic impurity, is pulled off by a magnetic roller. Wolframite is magnetic and is separated from cassiterite, which is not. Sulphides such as ZnS, Cu<sub>2</sub>S and PbS go through froth flotation.</p>`],
    [`Hydraulic washing (gravity separation) works because the ore particles are`, `heavier than the gangue particles`, [`lighter than the gangue`, `more magnetic than the gangue`, `wetted more by oil`], `<p>A stream of water carries off the lighter earthy gangue and leaves the heavier oxide ore, such as haematite or cassiterite, behind.</p>`],
    [`Silver sulphide ore is dissolved by dilute NaCN solution in air, giving`, `Na[Ag(CN)<sub>2</sub>]`, [`Na<sub>3</sub>[Ag(CN)<sub>4</sub>]`, `AgCN precipitate which does not dissolve`, `Ag<sub>2</sub>O`], `<p>Ag<sub>2</sub>S + 4NaCN &rarr; 2Na[Ag(CN)<sub>2</sub>] + Na<sub>2</sub>S. Silver is in the +1 state with a linear complex ion. Air is needed to oxidise the sulphide ion so the reaction goes on.</p>`],
    [`Silver is then recovered from the cyanide complex by`, `displacement with zinc dust`, [`heating with carbon`, `passing CO<sub>2</sub>`, `adding Fe<sub>2</sub>O<sub>3</sub>`], `<p>2[Ag(CN)<sub>2</sub>]<sup>&minus;</sup> + Zn &rarr; [Zn(CN)<sub>4</sub>]<sup>2&minus;</sup> + 2Ag. Zinc is more electropositive than silver.</p>`],
  ]),
  ...T(2, 'roasting and calcination', [
    [`Which pair is correctly matched with the usual first step?`, `Calamine (ZnCO<sub>3</sub>) &ndash; calcination`, [`Zinc blende &ndash; calcination`, `Haematite &ndash; roasting in excess air to remove sulphur`, `Cuprite &ndash; froth flotation to remove carbonate`], `<p>Carbonates are calcined to give the oxide: ZnCO<sub>3</sub> &rarr; ZnO + CO<sub>2</sub>. Sulphides such as zinc blende are roasted.</p>`],
    [`Limonite, Fe<sub>2</sub>O<sub>3</sub>&middot;xH<sub>2</sub>O, on calcination gives`, `Fe<sub>2</sub>O<sub>3</sub> and water vapour`, [`Fe<sub>3</sub>O<sub>4</sub> and H<sub>2</sub>`, `Fe and H<sub>2</sub>O<sub>2</sub>`, `FeCO<sub>3</sub>`], `<p>Calcination drives off water of hydration: Fe<sub>2</sub>O<sub>3</sub>&middot;xH<sub>2</sub>O &rarr; Fe<sub>2</sub>O<sub>3</sub> + xH<sub>2</sub>O.</p>`],
    [`Roasting of galena in excess air gives`, `PbO and SO<sub>2</sub>`, [`Pb and SO<sub>3</sub>`, `PbSO<sub>4</sub> only`, `PbCO<sub>3</sub>`], `<p>2PbS + 3O<sub>2</sub> &rarr; 2PbO + 2SO<sub>2</sub>. The oxide is then reduced by carbon, or by unroasted PbS in self-reduction.</p>`],
    [`The gas given off in roasting sulphide ores is poisonous and is usually`, `trapped and turned into sulphuric acid`, [`used as the reducing agent in the same furnace`, `released to the air, since it is harmless`, `condensed to give sulphur dioxide as a solid residue`], `<p>SO<sub>2</sub> is a pollutant that causes acid rain. Plants convert it to H<sub>2</sub>SO<sub>4</sub> by the contact process.</p>`],
  ]),
  ...T(2, 'reduction', [
    [`Heating a mixture of Cr<sub>2</sub>O<sub>3</sub> and aluminium powder gives chromium. This is called`, `the thermite (aluminothermy or Goldschmidt) process`, [`the Mond process`, `the van Arkel process`, `cupellation`], `<p>Cr<sub>2</sub>O<sub>3</sub> + 2Al &rarr; Al<sub>2</sub>O<sub>3</sub> + 2Cr. A lot of heat is given out, as Al has a greater affinity for oxygen than Cr. The same trick joins rails with Fe<sub>2</sub>O<sub>3</sub>.</p>`],
    [`The main reducing agent in the blast furnace for iron is`, `CO, formed from coke`, [`H<sub>2</sub> from the stoves`, `aluminium`, `silica`], `<p>Coke burns to CO<sub>2</sub> and then CO<sub>2</sub> + C &rarr; 2CO. CO takes the oxygen from the oxide ores: Fe<sub>2</sub>O<sub>3</sub> + 3CO &rarr; 2Fe + 3CO<sub>2</sub>.</p>`],
    [`In the extraction of copper from Cu<sub>2</sub>S, the roasted ore partly gives Cu<sub>2</sub>O, which reacts with the remaining Cu<sub>2</sub>S as 2Cu<sub>2</sub>O + Cu<sub>2</sub>S &rarr; 6Cu + SO<sub>2</sub>. This is called`, `self-reduction (auto-reduction)`, [`electrolytic reduction`, `calcination`, `slag formation`], `<p>No outside reducing agent is used: the sulphide itself reduces the oxide. Pb and Hg are also got in this way.</p>`],
    [`Zinc oxide is reduced by coke at about`, `1673 K, and the zinc leaves as vapour`, [`373 K, and the zinc stays as a solid`, `673 K as a liquid pool`, `3000 K`], `<p>ZnO + C &rarr; Zn + CO at about 1673 K. This is above the boiling point of zinc (1180 K), so zinc distils and is condensed.</p>`],
    [`Cinnabar (HgS) is converted to mercury merely by`, `roasting in air`, [`electrolysing the fused ore`, `heating with coke at 1700 K`, `leaching with NaCN`], `<p>HgS + O<sub>2</sub> &rarr; Hg + SO<sub>2</sub>. HgO is so unstable that it decomposes on heating, so the metal is obtained directly and distils off.</p>`],
    [`In the extraction of iron from haematite, limestone is added to`, `form a slag with the silica gangue`, [`reduce Fe<sub>2</sub>O<sub>3</sub> to FeO`, `supply the heat by burning`, `raise the carbon content to 4%`], `<p>CaCO<sub>3</sub> &rarr; CaO + CO<sub>2</sub> and CaO + SiO<sub>2</sub> &rarr; CaSiO<sub>3</sub>. The slag floats on the molten iron and keeps it from re-oxidation.</p>`],
  ]),
  ...T(2, 'Ellingham diagram', [
    [`In an Ellingham diagram the line for M &rarr; MO (a solid metal forming an oxide) slopes upward because`, `&Delta;S&deg; is negative, since a gas (O<sub>2</sub>) is used up`, [`&Delta;H&deg; is positive`, `&Delta;S&deg; is positive, as an oxide has more entropy`, `&Delta;G&deg; is independent of temperature`], `<p>&Delta;G&deg; = &Delta;H&deg; &minus; T&Delta;S&deg;. The slope against T is &minus;&Delta;S&deg;. With &Delta;S&deg; negative, the slope is positive.</p>`],
    [`The line for 2C + O<sub>2</sub> &rarr; 2CO slopes downward because`, `&Delta;S&deg; is positive (1 mol of gas becomes 2 mol of gas)`, [`&Delta;S&deg; is negative`, `&Delta;H&deg; is positive and large`, `CO is a solid`], `<p>The slope is &minus;&Delta;S&deg;. Two moles of gas are formed from one, so &Delta;S&deg; &gt; 0 and the slope is negative. This is why carbon reduces more oxides as the temperature rises.</p>`],
    [`A metal oxide can be reduced by carbon at a temperature where`, `the C &rarr; CO line lies below the metal-oxide line`, [`the C &rarr; CO line lies above the metal-oxide line`, `the two lines are parallel`, `the oxide line is at its highest point`], `<p>The net reaction MO + C &rarr; M + CO has &Delta;G&deg; = &Delta;G&deg;(C &rarr; CO) &minus; &Delta;G&deg;(M &rarr; MO) per mole of O. It is negative when the carbon line is below.</p>`],
    [`In the Ellingham diagram a sharp rise in slope for a metal's oxide line usually marks`, `the melting or boiling point of the metal`, [`the melting point of the oxide's impurities`, `the point where carbon starts to burn`, `a mistake`], `<p>Melting or boiling of the metal increases its entropy, so &Delta;S&deg; of oxidation becomes more negative, and the slope &minus;&Delta;S&deg; becomes more positive.</p>`],
    [`A metal whose oxide line lies far below the others in the Ellingham diagram, such as Mg or Al,`, `is a strong reducing agent and can reduce the oxides above it`, [`cannot reduce any oxide`, `is reduced easily by carbon at 1000 K`, `forms oxides that decompose on heating`], `<p>A lower line means a larger negative &Delta;G&deg; for forming the oxide, so the metal is a strong reductant and can take oxygen from any oxide whose line is above.</p>`],
  ]),
  ...T(2, 'extraction of metals', [
    [`In the electrolysis of alumina, cryolite is added mainly to`, `lower the melting point and make the melt conduct`, [`oxidise aluminium at the anode`, `act as the cathode`, `reduce Al<sup>3+</sup>`], `<p>Pure alumina melts at above 2300 K and conducts poorly. With cryolite and fluorspar the cell runs at about 1200 K.</p>`],
    [`The reaction at the cathode in the Hall&ndash;H&eacute;roult cell is`, `Al<sup>3+</sup> + 3e<sup>&minus;</sup> &rarr; Al(l)`, [`2O<sup>2&minus;</sup> &rarr; O<sub>2</sub> + 4e<sup>&minus;</sup>`, `Al &rarr; Al<sup>3+</sup> + 3e<sup>&minus;</sup>`, `C + O<sup>2&minus;</sup> &rarr; CO + 2e<sup>&minus;</sup>`], `<p>Reduction is at the cathode. The oxide ions go to the anode and burn the carbon to CO and CO<sub>2</sub>.</p>`],
    [`Sodium metal is manufactured by`, `electrolysis of fused NaCl with CaCl<sub>2</sub> (Downs process)`, [`reduction of Na<sub>2</sub>O with carbon`, `electrolysis of aqueous NaCl`, `heating NaCl with iron`], `<p>The very reactive metals (Li, Na, K, Mg, Ca) come from their fused salts. In water the hydrogen would be discharged instead.</p>`],
    [`The chief ore of magnesium is`, `carnallite, KCl&middot;MgCl<sub>2</sub>&middot;6H<sub>2</sub>O (and magnesite, dolomite)`, [`bauxite`, `cuprite`, `cinnabar`], `<p>Magnesium is made by electrolysing fused MgCl<sub>2</sub>.</p>`],
    [`Wrought iron is the purest form of iron because it`, `has the least carbon (about 0.1 to 0.25%)`, [`has the most carbon`, `is made in the blast furnace directly`, `contains no slag at all`], `<p>Pig iron is purified in a puddling furnace lined with haematite, where carbon, Si, S and P are oxidised away. A little slag remains in the fibres.</p>`, `Wrought iron does contain a little slag.`],
    [`Blister copper is called so because`, `SO<sub>2</sub> escapes as it solidifies and leaves a blistered surface`, [`it contains blisters of Au and Ag`, `it is full of water`, `of the hot slag`], `<p>Dissolved SO<sub>2</sub> bursts out on cooling. Blister copper is about 98% pure and goes on to electrolytic refining.</p>`],
  ]),
  ...T(2, 'refining', [
    [`Which metal is purified by distillation?`, `Zinc, cadmium or mercury`, [`Tin`, `Silver`, `Titanium`], `<p>These low-boiling metals are distilled away from non-volatile impurities.</p>`],
    [`Liquation is used to purify`, `tin (low melting metals such as Sn, Pb, Bi)`, [`copper`, `aluminium`, `titanium`], `<p>The impure metal is heated on a sloping hearth. The low-melting metal runs down and the infusible impurities stay behind.</p>`],
    [`Cupellation is used for the purification of`, `silver containing lead`, [`copper containing silver`, `iron with carbon`, `zinc`], `<p>Lead is oxidised to PbO, which is absorbed by the porous bone-ash cupel, and silver is left behind.</p>`],
    [`Poling of copper involves stirring the molten metal with`, `green wood poles, whose gases reduce Cu<sub>2</sub>O`, [`iron rods`, `graphite electrodes`, `liquid sodium`], `<p>Hydrocarbons from the green wood reduce the small amount of Cu<sub>2</sub>O in the metal to copper.</p>`],
    [`In the electrolytic refining of copper, the anode mud contains`, `Ag, Au, Pt, Se and Te`, [`Zn and Fe`, `Cu<sub>2</sub>O`, `CuSO<sub>4</sub>`], `<p>Less electropositive impurities do not dissolve; they fall as anode mud. Fe and Zn dissolve but stay in solution since their discharge potential is not reached.</p>`],
    [`In the Mond process, nickel is heated in a stream of`, `CO at about 330&ndash;350 K to give a volatile carbonyl`, [`Cl<sub>2</sub> at 2000 K`, `I<sub>2</sub> at 870 K`, `H<sub>2</sub> at 1500 K`], `<p>Ni + 4CO &rarr; Ni(CO)<sub>4</sub> at about 330&ndash;350 K, and the carbonyl decomposes at about 450&ndash;470 K to pure nickel.</p>`],
    [`In the van Arkel method, crude zirconium is heated with`, `iodine, and the ZrI<sub>4</sub> is decomposed on a tungsten filament`, [`CO, and the carbonyl is decomposed`, `chlorine at 400 K`, `NaCN solution`], `<p>Zr + 2I<sub>2</sub> &rarr; ZrI<sub>4</sub> (about 870 K), and ZrI<sub>4</sub> &rarr; Zr + 2I<sub>2</sub> on the hot (about 2075 K) filament. Ti is purified in the same way.</p>`],
    [`Column chromatography is chosen for refining when`, `the metal is available only in small amounts and the impurities are very like it`, [`the metal is available in tonnes`, `the metal is a gas`, `the metal is magnetic`], `<p>The mixture is passed through a column of alumina, and the components are held back by different amounts.</p>`],
  ]),
];

const H3 = [
  ...T(3, 'concentration and roasting', [
    [`In the cyanide process for gold, the leaching agent and the oxidiser are`, `NaCN and O<sub>2</sub> from the air`, [`NaOH and CO<sub>2</sub>`, `HCl and Cl<sub>2</sub>`, `KCN and H<sub>2</sub>`], `<p>4Au + 8CN<sup>&minus;</sup> + 2H<sub>2</sub>O + O<sub>2</sub> &rarr; 4[Au(CN)<sub>2</sub>]<sup>&minus;</sup> + 4OH<sup>&minus;</sup>. Gold needs an oxidiser to dissolve, and air serves.</p>`, `The cyanide complex of gold has gold(I), not gold(0).`],
    [`The sulphide ore of the metal M is roasted to give MO and SO<sub>2</sub>, and then M is got by heating MO with MS: MS + 2MO &rarr; 3M + SO<sub>2</sub>. M could be`, `lead`, [`zinc`, `iron`, `aluminium`], `<p>Self-reduction works for PbS and for Cu<sub>2</sub>S (the sulphides of the less reactive metals). Zinc oxide is not reduced by ZnS, and Fe and Al oxides are far too stable.</p>`],
    [`In the extraction of copper, iron is removed from the matte mainly as`, `FeSiO<sub>3</sub> slag`, [`Fe(CO)<sub>5</sub> vapour`, `FeS gas`, `Fe<sub>2</sub>O<sub>3</sub> sublimate`], `<p>FeO + SiO<sub>2</sub> &rarr; FeSiO<sub>3</sub>. Silica is an acidic flux for the basic FeO. In the converter 2FeS + 3O<sub>2</sub> &rarr; 2FeO + 2SO<sub>2</sub> happens first because FeS takes oxygen before Cu<sub>2</sub>S.</p>`],
    [`The flux used when the gangue is silica (acidic) is`, `CaO (basic flux)`, [`SiO<sub>2</sub>`, `P<sub>4</sub>O<sub>10</sub>`, `CO<sub>2</sub>`], `<p>An acidic gangue needs a basic flux, and a basic gangue needs an acidic flux (SiO<sub>2</sub>).</p>`, `Match the flux to the gangue by opposite acid-base character.`],
    [`Cu<sub>2</sub>S can be directly treated in the converter, but FeS in the matte is oxidised first. The reason is that`, `iron has the larger affinity for oxygen (its oxide line lies lower)`, [`Cu<sub>2</sub>S is more volatile than FeS`, `FeS is a good reducing agent for copper`, `SiO<sub>2</sub> reacts with Cu<sub>2</sub>S first`], `<p>The oxide of iron is more stable than the oxide of copper per mole of oxygen, and sulphur has a greater affinity for copper than iron has. So FeS is oxidised first and Cu<sub>2</sub>S is left.</p>`],
    [`Which statement about the leaching of bauxite is true?`, `Pure Al(OH)<sub>3</sub> is got by passing CO<sub>2</sub> into the sodium aluminate solution`, [`Pure Al(OH)<sub>3</sub> is got by adding NaOH to the solution`, `Fe<sub>2</sub>O<sub>3</sub> dissolves in NaOH and Al<sub>2</sub>O<sub>3</sub> is left`, `The solution is heated until the water boils away to give Al<sub>2</sub>O<sub>3</sub>`], `<p>Na[Al(OH)<sub>4</sub>] + CO<sub>2</sub> &rarr; Al(OH)<sub>3</sub>&darr; + NaHCO<sub>3</sub>. Heating Al(OH)<sub>3</sub> (about 1470 K) gives pure Al<sub>2</sub>O<sub>3</sub>. Extra NaOH would only keep it dissolved.</p>`],
  ]),
  ...T(3, 'thermodynamics of reduction', [
    [`For the reaction MO + C &rarr; M + CO to occur on heating, the necessary condition is that`, `&Delta;G&deg; of the net reaction is negative, which happens above the temperature where the two lines cross`, [`&Delta;H&deg; must be zero`, `&Delta;S&deg; must be negative`, `T must be below the crossing point`], `<p>The lines cross where &Delta;G&deg;(net) = 0. Above that temperature the carbon line is lower, so &Delta;G&deg;(net) &lt; 0 and the reaction goes.</p>`],
    [`Why is Al<sub>2</sub>O<sub>3</sub> not reduced by carbon in an ordinary furnace?`, `Its &Delta;G&deg; of formation is so negative that the C &rarr; CO line meets it only at a very high temperature`, [`Because carbon is a gas at such temperatures`, `Aluminium has a higher melting point than carbon`, `Carbon is not a reducing agent`], `<p>The carbon line reaches the Al<sub>2</sub>O<sub>3</sub> line only well above 2000 K. That is uneconomical, and Al would form Al<sub>4</sub>C<sub>3</sub>, so electrolysis is used.</p>`],
    [`An Ellingham line for CO<sub>2</sub> formation (C + O<sub>2</sub> &rarr; CO<sub>2</sub>) is almost horizontal because`, `the number of gas molecules does not change, so &Delta;S&deg; is about zero`, [`&Delta;H&deg; is zero`, `carbon is a liquid there`, `CO<sub>2</sub> is a solid at those temperatures`], `<p>One mole of O<sub>2</sub> gas gives one mole of CO<sub>2</sub> gas. &Delta;S&deg; is near zero, so &Delta;G&deg; hardly changes with T.</p>`],
    [`Below about 1000 K, the best reducing agent for iron oxide in the blast furnace is CO rather than C, because`, `the line for 2CO + O<sub>2</sub> &rarr; 2CO<sub>2</sub> is lower than the C &rarr; CO line at such temperatures`, [`CO is a solid at such temperatures`, `C and Fe<sub>2</sub>O<sub>3</sub> are both gases`, `CO has a higher &Delta;S&deg; than C`], `<p>At lower temperatures the CO &rarr; CO<sub>2</sub> line is below the C &rarr; CO line, and CO is the better reductant. Higher up, direct reduction by carbon takes over.</p>`],
    [`Metals whose oxides decompose on heating alone, so their oxide lines cross &Delta;G&deg; = 0 at a modest temperature, include`, `Hg and Ag`, [`Zn and Mg`, `Al and Ca`, `Na and K`], `<p>Their oxide lines are high up, crossing zero at a modest temperature, so the oxides break down on heating. Roasting HgS thus gives Hg directly.</p>`],
    [`A reaction has &Delta;H&deg; = +180 kJ and &Delta;S&deg; = +200 J K<sup>&minus;1</sup>. It is spontaneous (standard conditions) when`, `T is above 900 K`, [`T is below 900 K`, `T is above 360 K`, `at any temperature`], `<p>&Delta;G&deg; = 180000 &minus; 200 T &lt; 0 &rArr; T &gt; 900 K.</p>`, `Convert kJ and J to the same unit.`],
  ]),
  ...T(3, 'extraction of iron and steel', [
    [`In the blast furnace, the reaction Fe<sub>2</sub>O<sub>3</sub> + 3CO &rarr; 2Fe + 3CO<sub>2</sub> is called`, `indirect reduction`, [`direct reduction`, `calcination`, `smelting with a flux`], `<p>Indirect reduction uses CO. Direct reduction uses solid carbon, such as FeO + C &rarr; Fe + CO.</p>`],
    [`The temperature is highest in which zone of the blast furnace?`, `Near the tuyeres at the bottom, where coke burns`, [`Top of the furnace`, `At the slag line only`, `The cooling water jackets`], `<p>Hot blast burns coke at the bottom: C + O<sub>2</sub> &rarr; CO<sub>2</sub>, which is highly exothermic, and gives about 2000 K.</p>`],
    [`Pig iron is changed into wrought iron by`, `oxidising away the carbon and impurities in a puddling furnace lined with haematite`, [`adding more coke`, `adding limestone only`, `electrolysis`], `<p>Fe<sub>2</sub>O<sub>3</sub> is an oxidising lining. C, Si, S, P and Mn are oxidised and removed as gas or slag.</p>`],
    [`Which step is NOT part of the blast furnace?`, `Roasting FeS<sub>2</sub> with silica to make FeSiO<sub>3</sub> matte`, [`CaCO<sub>3</sub> &rarr; CaO + CO<sub>2</sub>`, `CaO + SiO<sub>2</sub> &rarr; CaSiO<sub>3</sub>`, `Fe<sub>3</sub>O<sub>4</sub> + 4CO &rarr; 3Fe + 4CO<sub>2</sub>`], `<p>Matte formation is a copper-extraction step. The other three occur in the iron furnace.</p>`],
    [`Gas at the top of the blast furnace is mainly CO<sub>2</sub>, N<sub>2</sub> and CO. The reason CO is still present is that`, `the reduction of iron oxide by CO is reversible, so excess CO is needed`, [`CO is formed by cracking limestone`, `CO is inert and plays no part`, `iron is a catalyst only`], `<p>Fe<sub>2</sub>O<sub>3</sub> + 3CO &rightleftharpoons; 2Fe + 3CO<sub>2</sub>. Fe is oxidised again if CO<sub>2</sub> accumulates; so an excess of CO is kept.</p>`],
  ]),
  ...T(3, 'refining', [
    [`During the electrolytic refining of copper, the electrolyte stays the same strength because`, `as much Cu dissolves at the anode as is deposited at the cathode`, [`no copper dissolves at the anode`, `silver deposits in place of copper`, `the electrolyte is continuously renewed with fresh copper sulphate`], `<p>Cu &rarr; Cu<sup>2+</sup> + 2e<sup>&minus;</sup> at the anode and Cu<sup>2+</sup> + 2e<sup>&minus;</sup> &rarr; Cu at the cathode, in equal amounts, though the impurity ions build up.</p>`],
    [`Zone refining depends on the fact that`, `impurities are more soluble in the molten metal than in the solid metal`, [`impurities are insoluble in both`, `impurities are more soluble in the solid metal`, `the rod is converted to a gas at the zone`], `<p>A heater moves along the rod. The impurities travel with the molten zone and are swept to one end, which is then cut off.</p>`],
    [`Which metal is refined by a method in which the metal forms a volatile compound that is later decomposed?`, `Nickel, as Ni(CO)<sub>4</sub>`, [`Lead, by cupellation`, `Copper, by poling`, `Tin, by liquation`], `<p>That is vapour phase refining (Mond, van Arkel). The other methods do not involve a volatile compound of the metal.</p>`],
    [`The oxidation state and shape of nickel in Ni(CO)<sub>4</sub> are`, `0 and tetrahedral`, [`+4 and square planar`, `+2 and tetrahedral`, `0 and square planar`], `<p>CO is a neutral ligand, so Ni is in the 0 state (3d<sup>8</sup>4s<sup>2</sup> becomes 3d<sup>10</sup>). With sp<sup>3</sup> hybridisation it is tetrahedral and diamagnetic.</p>`],
    [`The reason why the Mond process cannot be used for iron or cobalt is best stated as`, `Fe and Co also form carbonyls, but they do so under high pressure, and not under the mild conditions where Ni does`, [`Fe and Co form no carbonyls at all`, `Fe and Co carbonyls are non-volatile solids at any temperature`, `Fe and Co are gases`], `<p>Ni reacts with CO at about 330&ndash;350 K at ordinary pressure. Fe(CO)<sub>5</sub> needs high pressure and temperature, and Co carbonyls need high pressure.</p>`],
  ]),
];

const H4 = [
  ...T(4, 'Ellingham diagram', [
    [`Two oxide lines in the Ellingham diagram cross at T<sub>0</sub>. For T &gt; T<sub>0</sub> the metal of the lower line (at that T)`, `can reduce the oxide of the metal of the upper line`, [`cannot reduce it`, `is reduced by it`, `forms a carbide with it only`], `<p>The oxide with the more negative &Delta;G&deg; is the more stable. Its metal takes oxygen from the oxide that is less stable. This works for any pair of lines, not only for carbon.</p>`],
    [`Which statement about the Ellingham diagram is correct?`, `&Delta;G&deg; = &minus;RT ln K is used, so the diagram shows only thermodynamic feasibility and not the rate`, [`it tells the rate of reduction`, `it shows the actual temperature at which a reaction starts in practice`, `it applies only when the reactants are gases`], `<p>A negative &Delta;G&deg; says the reaction can occur, but not how fast. Kinetics may still prevent it. Also, it uses standard states and not the actual concentrations.</p>`, `A feasible reaction can still be slow.`],
    [`The Ellingham line for the oxidation of Zn is above that for the oxidation of Mg at 1500 K. A correct conclusion is that`, `Mg can reduce ZnO at 1500 K, and Zn cannot reduce MgO`, [`Zn can reduce MgO`, `both oxides decompose at 1500 K`, `Zn and Mg have the same affinity for oxygen`], `<p>The lower line (Mg) is more stable. Mg takes oxygen from ZnO: ZnO + Mg &rarr; Zn + MgO has a negative &Delta;G&deg;.</p>`],
    [`In an Ellingham diagram the slope of M &rarr; MO changes at the boiling point of M. The change in the slope equals`, `&Delta;S&deg;(vaporisation of M) per mole of O<sub>2</sub> consumed, taken as an increase`, [`&minus;&Delta;S&deg;(fusion) with a decrease`, `zero`, `&Delta;H&deg;(vaporisation)`], `<p>For 2M + O<sub>2</sub> &rarr; 2MO, going from M(l) to M(g) adds 2&Delta;S<sub>vap</sub> to the loss of entropy of the reactants, so &Delta;S&deg; falls and the slope (&minus;&Delta;S&deg;) rises by 2&Delta;S<sub>vap</sub>, which is large (about 2 &times; 100 J K<sup>&minus;1</sup>).</p>`],
  ]),
  ...T(4, 'concentration, roasting and refining', [
    [`In the cyanide leaching of silver or gold, air is bubbled through the solution because`, `oxygen is needed to oxidise the metal (or the sulphide) so that it goes into solution as a complex`, [`oxygen is the reducing agent that gives the metal`, `air must be kept out to protect the metal`, `nitrogen in air forms a nitride complex`], `<p>The metal has to be oxidised to dissolve: 4Au + 8CN<sup>&minus;</sup> + 2H<sub>2</sub>O + O<sub>2</sub> &rarr; 4[Au(CN)<sub>2</sub>]<sup>&minus;</sup> + 4OH<sup>&minus;</sup>. O<sub>2</sub> is the oxidiser; zinc dust later does the reduction.</p>`, `Dissolving the metal is an oxidation, so air helps and does not harm.`],
    [`In the smelting of roasted copper pyrites with silica, the molten layer that sinks below the slag is`, `matte (Cu<sub>2</sub>S with FeS)`, [`blister copper`, `pig iron`, `anode mud`], `<p>The slag (FeSiO<sub>3</sub>) floats. The denser matte, which contains Cu<sub>2</sub>S and some FeS, is tapped off and sent to the converter.</p>`],
    [`Which metallurgical step is the main source of SO<sub>2</sub>, a cause of acid rain?`, `roasting of sulphide ores`, [`calcination of limestone`, `electrolysis of alumina`, `zone refining`], `<p>Roasting turns sulphide sulphur into SO<sub>2</sub>. This is why plants collect it and make sulphuric acid.</p>`],
    [`A student heats Cu<sub>2</sub>O with carbon (no sulphide). The reaction is`, `Cu<sub>2</sub>O + C &rarr; 2Cu + CO, and it works at a moderate temperature`, [`not possible at any temperature`, `needs 3000 K`, `makes Cu<sub>2</sub>C only`], `<p>The oxide line of copper lies high up in the Ellingham diagram; the carbon line is below it already at modest temperatures. So carbon reduction is easy.</p>`],
    [`Zinc, cadmium and mercury can all be refined by distillation because they`, `are volatile, with boiling points much lower than those of their impurities`, [`are magnetic`, `form volatile carbonyls`, `have melting points higher than their impurities`], `<p>The impure metal is vaporised and the vapour condensed, leaving non-volatile impurities behind.</p>`],
  ]),
  ...T(4, 'mixed', [
    [`Ni(CO)<sub>4</sub> and [Ni(CN)<sub>4</sub>]<sup>2&minus;</sup> differ in that`, `the first is tetrahedral and diamagnetic with Ni(0), the second is square planar and diamagnetic with Ni(II)`, [`both are tetrahedral`, `both are paramagnetic`, `both have Ni in the +2 state`], `<p>CO (neutral) with Ni(0), d<sup>10</sup>, gives sp<sup>3</sup>. CN<sup>&minus;</sup> is a strong-field ligand, and Ni(II) is d<sup>8</sup>, which pairs up for dsp<sup>2</sup> square planar.</p>`],
    [`The linear complex ion in the silver cyanide leaching is [Ag(CN)<sub>2</sub>]<sup>&minus;</sup>. The hybridisation of silver in it is`, `sp`, [`sp<sup>3</sup>`, `dsp<sup>2</sup>`, `sp<sup>3</sup>d<sup>2</sup>`], `<p>Ag(I) is 4d<sup>10</sup>, so it uses the vacant 5s and 5p orbitals: sp, linear.</p>`],
    [`Zinc dust is used to recover Ag from [Ag(CN)<sub>2</sub>]<sup>&minus;</sup>. This is a displacement reaction possible because`, `E&deg;(Zn<sup>2+</sup>/Zn) is more negative than E&deg;(Ag<sup>+</sup>/Ag)`, [`Zn has the higher atomic mass`, `Ag is more reactive than Zn`, `Zn is a gas at the temperature used`], `<p>Zn is the stronger reducing agent. The cyanide complex stays in solution as [Zn(CN)<sub>4</sub>]<sup>2&minus;</sup>.</p>`],
    [`Which statement about heating the oxide of an electropositive metal like sodium with carbon is correct?`, `It does not give the metal because the Na<sub>2</sub>O line stays below the carbon line in practical ranges`, [`It gives Na easily`, `It gives Na<sub>2</sub>CO<sub>3</sub> only because carbon is oxidised first`, `It is the industrial method`], `<p>The oxides of the very electropositive metals are too stable for reduction by carbon. Fused-salt electrolysis is used instead.</p>`],
  ]),
];

const HAND5 = [
  ...T(5, 'Ellingham diagram', [
    [`Take these hypothetical lines (kJ per mole of O<sub>2</sub>): MO formation &Delta;G&deg; = &minus;500 + 0.15T; 2C + O<sub>2</sub> &rarr; 2CO: &minus;200 &minus; 0.20T; 2CO + O<sub>2</sub> &rarr; 2CO<sub>2</sub>: &minus;560 + 0.17T. At 1000 K, the reductant that gives the more negative &Delta;G&deg; for reducing MO, and its value per mole of O<sub>2</sub>, are`, `carbon (to CO), &minus;50 kJ`, [`carbon monoxide, &minus;50 kJ`, `carbon monoxide, &minus;40 kJ`, `carbon (to CO), +50 kJ`], `<p>At 1000 K: MO line = &minus;350; C line = &minus;400; CO line = &minus;390.</p><p>With carbon: &minus;400 &minus; (&minus;350) = &minus;50 kJ. With CO: &minus;390 &minus; (&minus;350) = &minus;40 kJ. Both are spontaneous, but carbon is more favourable here.</p>`, `Compute each line at the given T first, then subtract the oxide line.`],
    [`Consider two oxide lines, M and N, with &Delta;G&deg; = &minus;760 + 0.20T and &minus;1050 + 0.18T (kJ per mole O<sub>2</sub>). Metal N will reduce the oxide of M`, `at all temperatures from 0 K up to well above 1000 K, as long as the lines do not cross`, [`only above 1000 K`, `never`, `only below 100 K`], `<p>The lines cross where &minus;760 + 0.20T = &minus;1050 + 0.18T, so 0.02T = &minus;290, T = &minus;14500 K, which is not physical. So for every real temperature the N line is the lower one (more negative by 290 &minus; 0.02T kJ), and N reduces MO.</p>`],
  ]),
];

const HAND_NAT = [
  nat(2, 'Faraday', `How many faradays of charge are needed to obtain 54 g of aluminium from molten alumina in the Hall&ndash;H&eacute;roult cell? (Al = 27)`, 6, 0, 'F', `<p>Moles of Al = 54/27 = 2. Each needs 3 electrons: Al<sup>3+</sup> + 3e<sup>&minus;</sup> &rarr; Al.</p><p>Charge = 2 &times; 3 = <b>6 F</b>.</p>`, `Three electrons per Al atom, not one.`, () => 54 / 27 * 3),
  nat(3, 'electrolysis', `A steady current of 2 A passes through molten alumina for 9650 s. Find the mass of aluminium deposited at 100% efficiency. (Al = 27, 1 F = 96500 C)`, 1.8, 0.02, 'g', `<p>Charge Q = 2 &times; 9650 = 19300 C. Moles of electrons = 19300/96500 = 0.2.</p><p>Moles of Al = 0.2/3 = 0.0667. Mass = 0.0667 &times; 27 = <b>1.8 g</b>.</p>`, `Divide by 3 since three electrons deposit one Al.`, () => 27 * 2 * 9650 / 96500 / 3),
  nat(3, 'electrolytic refining', `A current of 5 A is passed for 1930 s through an acidified CuSO<sub>4</sub> cell in the refining of copper. Find the mass of copper deposited. (Cu = 63.5)`, 3.18, 0.03, 'g', `<p>Q = 5 &times; 1930 = 9650 C, so 0.1 mol of electrons.</p><p>Cu<sup>2+</sup> needs 2 e<sup>&minus;</sup>, so Cu = 0.05 mol, mass = 0.05 &times; 63.5 = <b>3.175 g</b> &asymp; 3.18 g.</p>`, `Cu<sup>2+</sup> takes two electrons, not one.`, () => 63.5 * 5 * 1930 / 96500 / 2),
  nat(2, 'extraction of iron', `How many kilograms of iron can be got from 320 kg of pure Fe<sub>2</sub>O<sub>3</sub>? (Fe = 56, O = 16)`, 224, 0, 'kg', `<p>Molar mass of Fe<sub>2</sub>O<sub>3</sub> = 160. Fe<sub>2</sub>O<sub>3</sub> has 112 g of Fe in 160 g.</p><p>Iron = 320 &times; 112/160 = <b>224 kg</b>.</p>`, undefined, () => 320 * 112 / 160),
  nat(3, 'purity of ore', `A haematite ore of 1000 kg contains 80% Fe<sub>2</sub>O<sub>3</sub> by mass. Find the mass of iron that can be extracted, in kg (Fe = 56, O = 16).`, 560, 0, 'kg', `<p>Fe<sub>2</sub>O<sub>3</sub> = 0.80 &times; 1000 = 800 kg. Iron = 800 &times; 112/160 = <b>560 kg</b>.</p>`, `Use only the Fe<sub>2</sub>O<sub>3</sub> part of the ore, not the whole mass.`, () => 800 * 112 / 160),
  nat(3, 'roasting', `How many litres of SO<sub>2</sub> at STP are produced when 485 g of ZnS are roasted completely? (Zn = 65, S = 32; molar volume 22.4 L)`, 112, 0.5, 'L', `<p>ZnS = 97 g/mol, so moles = 485/97 = 5.</p><p>2ZnS + 3O<sub>2</sub> &rarr; 2ZnO + 2SO<sub>2</sub>: 1 mol SO<sub>2</sub> per mol ZnS, so 5 mol. Volume = 5 &times; 22.4 = <b>112 L</b>.</p>`, undefined, () => 485 / 97 * 22.4),
  nat(2, 'calcination', `50 g of pure CaCO<sub>3</sub> is calcined fully. Find the loss in mass, in g (Ca = 40, C = 12, O = 16).`, 22, 0, 'g', `<p>CaCO<sub>3</sub> (100) &rarr; CaO (56) + CO<sub>2</sub> (44). The loss is the CO<sub>2</sub> given off.</p><p>50 g = 0.5 mol, so CO<sub>2</sub> = 0.5 &times; 44 = <b>22 g</b>.</p>`, undefined, () => 0.5 * 44),
  nat(3, 'Ellingham', `For the reduction MO + C &rarr; M + CO, &Delta;H&deg; = +300 kJ and &Delta;S&deg; = +200 J K<sup>&minus;1</sup>. At what temperature, in kelvin, does &Delta;G&deg; become zero?`, 1500, 0, 'K', `<p>&Delta;G&deg; = &Delta;H&deg; &minus; T&Delta;S&deg; = 0 &rArr; T = &Delta;H&deg;/&Delta;S&deg; = 300000/200 = <b>1500 K</b>.</p>`, `Change kJ to J before dividing.`, () => 300000 / 200),
  nat(4, 'coupled reactions', `At 1273 K, &Delta;G&deg; for 2C + O<sub>2</sub> &rarr; 2CO is &minus;400 kJ, and for 2M + O<sub>2</sub> &rarr; 2MO it is &minus;350 kJ (per mole of O<sub>2</sub> in each). Find &Delta;G&deg; in kJ for MO + C &rarr; M + CO, per mole of MO.`, -25, 0, 'kJ', `<p>Subtract the oxide equation from the carbon equation: 2MO + 2C &rarr; 2M + 2CO, with &Delta;G&deg; = &minus;400 &minus; (&minus;350) = &minus;50 kJ.</p><p>Per mole of MO this is <b>&minus;25 kJ</b>. It is negative, so the reduction goes at 1273 K.</p>`, `Halve the answer: the equation as written has 2 mol of MO.`, () => (-400 + 350) / 2),
  nat(3, 'composition', `Find the percentage of iron by mass in magnetite, Fe<sub>3</sub>O<sub>4</sub> (Fe = 56, O = 16).`, 72.41, 0.05, '%', `<p>Molar mass = 3 &times; 56 + 4 &times; 16 = 232. Iron = 168.</p><p>% Fe = 168/232 &times; 100 = <b>72.41 %</b>.</p>`, undefined, () => 168 / 232 * 100),
  nat(3, 'composition', `Find the percentage of copper by mass in malachite, CuCO<sub>3</sub>&middot;Cu(OH)<sub>2</sub> (Cu = 63.5, C = 12, O = 16, H = 1).`, 57.47, 0.05, '%', `<p>Mass = 2 &times; 63.5 + 12 + 3 &times; 16 + 2 &times; 17 = 127 + 12 + 48 + 34 = 221.</p><p>% Cu = 127/221 &times; 100 = <b>57.47 %</b>.</p>`, `Malachite has two copper atoms per formula unit.`, () => 127 / 221 * 100),
  nat(3, 'slag formation', `How many grams of silica are needed to turn 144 g of FeO into FeSiO<sub>3</sub> slag? (Fe = 56, Si = 28, O = 16)`, 120, 0, 'g', `<p>FeO + SiO<sub>2</sub> &rarr; FeSiO<sub>3</sub>. FeO = 72 g/mol, so 144 g = 2 mol. SiO<sub>2</sub> = 60 g/mol.</p><p>Mass = 2 &times; 60 = <b>120 g</b>.</p>`, undefined, () => 2 * 60),
  nat(4, 'Hall&ndash;H&eacute;roult', `The cell makes aluminium by 2Al<sub>2</sub>O<sub>3</sub> + 3C &rarr; 4Al + 3CO<sub>2</sub>. What mass of CO<sub>2</sub>, in g, is released when 108 g of aluminium is made? (Al = 27, C = 12, O = 16)`, 132, 0, 'g', `<p>108 g Al = 4 mol. By the equation 4 Al go with 3 CO<sub>2</sub>.</p><p>CO<sub>2</sub> = 3 &times; 44 = <b>132 g</b>.</p>`, `Assumes all the carbon goes to CO<sub>2</sub>; in a real cell some CO also forms.`, () => 3 * 44),
  nat(4, 'Ellingham', `The oxide line of M is &Delta;G&deg; = &minus;760 + 0.20T and the line for 2C + O<sub>2</sub> &rarr; 2CO is &Delta;G&deg; = &minus;220 &minus; 0.20T (kJ per mole O<sub>2</sub>, T in kelvin). At what temperature, in K, can carbon begin to reduce MO?`, 1350, 5, 'K', `<p>Carbon reduces MO when its line falls below the oxide line: &minus;220 &minus; 0.20T = &minus;760 + 0.20T.</p><p>0.40T = 540, so T = <b>1350 K</b>.</p>`, `Both lines are written per mole of O<sub>2</sub>, so they can be compared directly.`, () => 540 / 0.4),
  nat(4, 'Faraday', `A Hall&ndash;H&eacute;roult cell passes 50000 A for one hour at 90% current efficiency. Find the mass of aluminium formed, in kg (Al = 27, 1 F = 96500 C).`, 15.11, 0.05, 'kg', `<p>Q = 50000 &times; 3600 = 1.8 &times; 10<sup>8</sup> C. At 100% the moles of Al = Q/(3F) = 1.8 &times; 10<sup>8</sup>/289500 = 621.8, mass 16.79 kg.</p><p>At 90%: 0.9 &times; 16.79 = <b>15.11 kg</b>.</p>`, `The efficiency multiplies the mass, it does not change the stoichiometry.`, () => 0.9 * 27 * 50000 * 3600 / 289500 / 1000),
  nat(3, 'Mond process', `How many moles of CO are needed to convert 3 mol of impure nickel completely into Ni(CO)<sub>4</sub>?`, 12, 0, 'mol', `<p>Ni + 4CO &rarr; Ni(CO)<sub>4</sub>: four CO per Ni.</p><p>3 &times; 4 = <b>12 mol</b>.</p>`, undefined, () => 12),
  nat(4, 'Hall&ndash;H&eacute;roult', `If all the oxygen at the anode burns the carbon to CO<sub>2</sub>, what mass of carbon, in kg, is used up per 1.08 kg of Al made? (Al = 27, C = 12)`, 0.36, 0.01, 'kg', `<p>1.08 kg Al = 40 mol. 4 Al go with 3 C, so C = 30 mol = 0.36 kg.</p>`, `If CO forms instead, twice as much carbon is burnt per mole of oxygen atoms removed.`, () => 40 * 3 / 4 * 12 / 1000),
];

const HAND_MSQ = [
  msq(3, 'concentration', `Which of these pairs of ore and method of concentration are correct?`, [`Zinc blende, froth flotation`, `Haematite, gravity (hydraulic) washing`, `Bauxite, leaching with NaOH`, `Galena, cupellation`], [0, 1, 2], `<p>Sulphides use froth flotation; heavy oxide ores use gravity separation; bauxite is leached with NaOH. Cupellation is a way of refining silver, not of concentrating galena.</p>`, `Cupellation is a refining step.`),
  msq(4, 'reduction', `Which of these oxides can be reduced to the metal by heating with carbon at the temperature of a blast furnace?`, [`Fe<sub>2</sub>O<sub>3</sub>`, `ZnO (about 1673 K)`, `Cu<sub>2</sub>O`, `Al<sub>2</sub>O<sub>3</sub> (in an ordinary furnace)`], [0, 1, 2], `<p>The oxides of Fe, Zn and Cu lie above the C &rarr; CO line at suitable temperatures. Al<sub>2</sub>O<sub>3</sub> needs over 2300 K, so it is done by electrolysis.</p>`),
  msq(4, 'refining', `Which of these refining methods end with the pure metal got by decomposing a volatile compound?`, [`Mond process for Ni`, `van Arkel method for Zr`, `Zone refining of Ge`, `Electrolytic refining of Cu`], [0, 1], `<p>Ni(CO)<sub>4</sub> is decomposed by heating, and ZrI<sub>4</sub> on a hot filament. Zone refining uses a moving molten zone; electrolysis uses an electric current with no compound formed.</p>`),
  msq(3, 'Hall&ndash;H&eacute;roult', `In the Hall&ndash;H&eacute;roult process, which statements are correct?`, [`Cryolite lowers the melting point of the bath`, `The graphite anodes have to be replaced`, `Aluminium is made at the cathode`, `Pure Al<sub>2</sub>O<sub>3</sub> is electrolysed on its own at 1200 K`], [0, 1, 2], `<p>Alumina melts above 2300 K, so it is dissolved in cryolite. The anode carbon burns to CO and CO<sub>2</sub>, so the anodes wear out. Al<sup>3+</sup> is reduced at the cathode.</p>`),
  msq(4, 'extraction of copper', `In the extraction of copper from copper pyrites, which are true?`, [`Silica is added to remove iron as slag`, `Matte is a mixture of Cu<sub>2</sub>S and FeS`, `Self-reduction occurs in the converter`, `Blister copper is more than 99.9% pure`], [0, 1, 2], `<p>FeO + SiO<sub>2</sub> &rarr; FeSiO<sub>3</sub>. Matte is Cu<sub>2</sub>S with FeS. In the converter Cu<sub>2</sub>S and Cu<sub>2</sub>O react to give Cu. Blister copper is about 98%, so it is refined further.</p>`),
  msq(5, 'mixed', `Which of these statements about Ni(CO)<sub>4</sub> and [Ag(CN)<sub>2</sub>]<sup>&minus;</sup> are correct?`, [`Ni in Ni(CO)<sub>4</sub> is sp<sup>3</sup> hybridised`, `[Ag(CN)<sub>2</sub>]<sup>&minus;</sup> is linear`, `Ni(CO)<sub>4</sub> is paramagnetic`, `Ag in the cyanide complex is in the +1 state`], [0, 1, 3], `<p>Ni(0) is d<sup>10</sup> with no unpaired electron, so Ni(CO)<sub>4</sub> is diamagnetic and tetrahedral. Ag(I) is sp hybridised, giving a linear ion.</p>`, `Ni(CO)<sub>4</sub> has no unpaired electrons.`),
  msq(5, 'Ellingham', `Which of these are consistent with the Ellingham diagram?`, [`2C + O<sub>2</sub> &rarr; 2CO has a negative slope`, `Most metal-to-oxide lines have a positive slope`, `A metal with a lower line can reduce an oxide with a higher line`, `At the melting point of the metal its oxide line becomes less steep`], [0, 1, 2], `<p>Positive &Delta;S for CO gives a falling line. The oxidation of a metal uses gas, so its slope is positive. The lower line is more stable. At the melting point the slope becomes steeper, not less steep.</p>`),
];

const ASR = [
  asr(2, 'Hall&ndash;H&eacute;roult', `Cryolite is added to alumina before electrolysis.`, `Cryolite lowers the melting point of the mixture and makes it a better conductor.`, 0, `<p>Both true, and R explains A: alumina melts above 2300 K and is a poor conductor, so with cryolite the bath works at about 1200 K.</p>`),
  asr(2, 'roasting', `Zinc blende is roasted and not calcined.`, `Roasting means heating in excess air, which turns a sulphide into an oxide.`, 0, `<p>Zinc blende is a sulphide, so it needs oxygen. Calcination in no air would not oxidise the sulphur.</p>`),
  asr(2, 'froth flotation', `Froth flotation is used to concentrate sulphide ores.`, `Sulphide particles are wetted by oil and gangue is wetted by water.`, 0, `<p>Oil and the frother make the sulphide particles stick to bubbles, and they rise; the wetted gangue sinks. R explains A.</p>`),
  asr(3, 'reduction of alumina', `Carbon is a satisfactory reductant for Al<sub>2</sub>O<sub>3</sub> in an ordinary blast furnace.`, `Aluminium has a very large affinity for oxygen.`, 3, `<p>A is false: carbon does not reduce Al<sub>2</sub>O<sub>3</sub> below about 2300 K. R is true and it is exactly the reason why not.</p>`),
  asr(3, 'Ellingham', `The line for 2C + O<sub>2</sub> &rarr; 2CO has a negative slope in the Ellingham diagram.`, `The reaction increases the number of moles of gas, so &Delta;S&deg; is positive.`, 0, `<p>The slope is &minus;&Delta;S&deg;. Positive &Delta;S&deg; gives a negative slope, and R is the reason.</p>`),
  asr(3, 'calcination and roasting', `Calcination and roasting are both carried out below the melting point of the ore.`, `Calcination is done in a limited or no supply of air, and roasting in excess air.`, 1, `<p>Both are true. But R is about the air supply and does not explain why the temperature stays below the melting point, so R is not the explanation.</p>`),
  asr(3, 'cast iron', `Pig iron is more brittle than wrought iron.`, `Pig iron contains less carbon than wrought iron.`, 2, `<p>A is true. R is false: pig iron has about 4% carbon and wrought iron only 0.1 to 0.25%. The extra carbon (and other impurities) causes the brittleness.</p>`),
  asr(4, 'refining', `Impure copper is used as the anode in electrolytic refining.`, `Copper atoms are oxidised more easily than the Ag and Au in the impure sample.`, 0, `<p>Cu &rarr; Cu<sup>2+</sup> at the anode, while Ag and Au, being less active, do not dissolve and fall as anode mud. R explains why the copper dissolves and the noble metals do not.</p>`),
  asr(4, 'zone refining', `Zone refining gives extremely pure germanium.`, `Impurities are more soluble in the solid than in the melt.`, 2, `<p>A is true, but R is false. Impurities are more soluble in the molten zone, so the moving heater sweeps them to the end of the rod.</p>`),
  asr(4, 'ZnS and PbS', `NaCN is used as a depressant for ZnS in separating it from PbS.`, `NaCN forms a soluble complex with ZnS on the surface of its particles.`, 0, `<p>The complex Na<sub>2</sub>[Zn(CN)<sub>4</sub>] forms, ZnS no longer sticks to the bubbles, and PbS floats. R is the explanation.</p>`),
];

const STM = [
  stm(2, 'extraction of metals', `Aluminium is obtained by electrolysis of its fused oxide dissolved in cryolite.`, `Sodium is obtained by electrolysis of aqueous sodium chloride.`, 1, `<p>I is correct. II is wrong: in aqueous NaCl hydrogen is discharged at the cathode instead of Na. Fused NaCl with CaCl<sub>2</sub> is used.</p>`),
  stm(3, 'ores', `Cryolite is a mineral of aluminium and is the chief source of the metal.`, `Bauxite is the chief ore of aluminium.`, 2, `<p>I is wrong. Natural cryolite is rare and is not the source of the metal; the cryolite used is mostly synthetic and serves as a solvent. II is correct.</p>`),
  stm(3, 'slag', `A slag is a fusible product of a flux and gangue.`, `For a basic gangue the flux used is a basic flux such as CaO.`, 1, `<p>I is correct. II is wrong: a basic gangue needs an acidic flux (silica), and an acidic gangue a basic flux.</p>`),
  stm(3, 'refining', `In the Mond process, nickel is heated with CO at 330&ndash;350 K to give a volatile compound.`, `The carbonyl is decomposed at a higher temperature (450&ndash;470 K) to give pure nickel.`, 0, `<p>Both are correct. The same equilibrium moves each way with temperature.</p>`),
  stm(3, 'Ellingham', `An Ellingham line for MO formation gets steeper after the boiling point of the metal.`, `Entropy of the metal increases a lot on vaporisation, and &Delta;S&deg; of the reaction becomes more negative.`, 0, `<p>Both are correct, and II explains I.</p>`),
  stm(4, 'Ellingham', `A negative &Delta;G&deg; for a reduction at some temperature guarantees that the reduction will take place at a useful rate.`, `Metal oxide reductions by carbon are more favourable at higher temperatures.`, 2, `<p>I is wrong: &Delta;G&deg; gives feasibility but not the rate. II is correct (positive &Delta;S&deg; for gas formed).</p>`),
  stm(4, 'electrolysis', `1 F of charge deposits 9 g of Al.`, `1 F of charge deposits 31.75 g of Cu from a Cu<sup>2+</sup> solution.`, 0, `<p>1 F gives 1 mol of electrons. Al: 27/3 = 9 g. Cu: 63.5/2 = 31.75 g. Both are correct.</p>`),
  stm(5, 'refining', `Vapour phase refining needs a metal that forms a volatile compound easily.`, `Both nickel and iron are refined industrially under mild conditions by the Mond process.`, 1, `<p>I is correct. II is wrong: only nickel forms its carbonyl under mild conditions; iron needs higher pressure and temperature, so the Mond process is used for nickel.</p>`),
  cnt(3, 'blast furnace', `How many of the following are true? (i) Coke gives the heat and CO in the furnace. (ii) Limestone is used as a flux. (iii) The slag floats on the molten iron. (iv) The reducing zone is hotter than the zone near the tuyeres.`, [`1`, `2`, `3`, `4`], 2, `<p>(i), (ii) and (iii) are true. (iv) is false because the tuyere zone is the hottest. Count = <b>3</b>.</p>`),
  cnt(4, 'extraction of metals', `How many of these metals are produced mainly by electrolysis of the fused salt or oxide: Na, Mg, Al, Zn, Fe, Ca?`, [`3`, `4`, `5`, `6`], 1, `<p>Na, Mg, Al and Ca come from fused electrolytes (4). Zn and Fe are made by carbon reduction. Count = <b>4</b>.</p>`),
];

const MATCH = [
  mat(2, 'ores', 'm1', `Match each ore in List I with the metal in List II.`, `A-r, B-s, C-p, D-q`, [`A-s, B-r, C-p, D-q`, `A-r, B-s, C-q, D-p`, `A-p, B-s, C-r, D-q`], `<p>Cassiterite is SnO<sub>2</sub> (tin, r). Cinnabar is HgS (mercury, s). Siderite is FeCO<sub>3</sub> (iron, p). Argentite is Ag<sub>2</sub>S (silver, q).</p>`),
  mat(3, 'refining', 'm2', `Match the process in List I with what it refines in List II.`, `A-s, B-q, C-p, D-r`, [`A-q, B-s, C-p, D-r`, `A-s, B-q, C-r, D-p`, `A-p, B-q, C-s, D-r`], `<p>Mond: nickel (s). van Arkel: zirconium (q). Zone refining: germanium (p). Poling: blister copper (r).</p>`),
  mat(3, 'extraction steps', 'm3', `Match the step in List I with what is used or happens in List II.`, `A-r, B-s, C-p, D-q`, [`A-s, B-r, C-p, D-q`, `A-r, B-s, C-q, D-p`, `A-q, B-s, C-p, D-r`], `<p>Bauxite is leached with hot concentrated NaOH (r). Zinc blende is roasted (s). Limestone is calcined (p). Silver is displaced from its complex by zinc dust (q).</p>`),
  mat(4, 'blast furnace', 'm4', `Match each zone of the blast furnace in List I with the main events in List II.`, `A-r, B-s, C-q, D-p`, [`A-s, B-r, C-q, D-p`, `A-r, B-s, C-p, D-q`, `A-q, B-s, C-r, D-p`], `<p>At the top (500&ndash;800 K) Fe<sub>2</sub>O<sub>3</sub> goes to Fe<sub>3</sub>O<sub>4</sub> (r). In the middle zone FeO is reduced to Fe, and limestone decomposes (s). The slag zone gives CaSiO<sub>3</sub> (q). At the bottom coke burns (p).</p>`),
];

const PASSAGES = [
  P(3, 'Ellingham reading', 'p1', `Above which temperature, in kelvin, can carbon reduce the oxide of M?`, `1350 K`, [`950 K`, `760 K`, `2000 K`], `<p>Carbon reduces MO when &minus;220 &minus; 0.20T &lt; &minus;760 + 0.20T, so 0.40T &gt; 540 and T &gt; <b>1350 K</b>.</p>`, `Both lines are per mole of O<sub>2</sub>.`),
  P(4, 'Ellingham reading', 'p1', `At 1500 K, can metal N reduce the oxide of metal M?`, `Yes, because the N line (&minus;780 kJ) lies below the M line (&minus;460 kJ)`, [`No, because the M line is lower`, `No, because both lines are positive`, `Yes, but only above 2500 K`], `<p>At 1500 K: M line = &minus;760 + 300 = &minus;460 kJ. N line = &minus;1050 + 270 = &minus;780 kJ. N is lower, so it reduces MO: &Delta;G&deg; = &minus;780 &minus; (&minus;460) = &minus;320 kJ per mole O<sub>2</sub>.</p>`),
  PN(4, 'Ellingham reading', 'p1', `Find &Delta;G&deg;, in kJ, per mole of O<sub>2</sub> for the reaction in which N reduces the oxide of M at 1000 K.`, -310, 0, 'kJ', `<p>N line at 1000 K = &minus;1050 + 180 = &minus;870. M line = &minus;760 + 200 = &minus;560.</p><p>&Delta;G&deg; = &minus;870 &minus; (&minus;560) = <b>&minus;310 kJ</b>.</p>`, undefined, () => (-1050 + 180) - (-760 + 200)),
  P(2, 'copper extraction', 'p2', `The slag formed in the reverberatory furnace is mostly`, `FeSiO<sub>3</sub>`, [`CaSiO<sub>3</sub>`, `Cu<sub>2</sub>SiO<sub>3</sub>`, `FeS`], `<p>FeO from roasting meets the silica flux: FeO + SiO<sub>2</sub> &rarr; FeSiO<sub>3</sub>, which floats on the matte.</p>`),
  P(3, 'copper extraction', 'p2', `In the converter, the reaction that gives metallic copper is`, `2Cu<sub>2</sub>O + Cu<sub>2</sub>S &rarr; 6Cu + SO<sub>2</sub>`, [`Cu<sub>2</sub>O + C &rarr; 2Cu + CO`, `CuO + H<sub>2</sub> &rarr; Cu + H<sub>2</sub>O`, `Cu<sub>2</sub>S &rarr; 2Cu + S by electrolysis`], `<p>FeS is oxidised and slagged first. Then part of Cu<sub>2</sub>S is oxidised to Cu<sub>2</sub>O, which reacts with the rest of the Cu<sub>2</sub>S by self-reduction.</p>`),
  P(3, 'copper extraction', 'p2', `Why does the final solid copper have a blistered surface?`, `Dissolved SO<sub>2</sub> escapes as the metal solidifies`, [`CO<sub>2</sub> escapes from the carbonate`, `Cu<sub>2</sub>O forms blisters of oxide`, `water vapour condenses on it`], `<p>SO<sub>2</sub> dissolved in the molten copper is expelled on solidification, leaving blisters. This gives the name blister copper.</p>`),
  P(3, 'Hall&ndash;H&eacute;roult', 'p3', `The cathode reaction and the number of electrons per mole of aluminium are`, `Al<sup>3+</sup> + 3e<sup>&minus;</sup> &rarr; Al, with 3 electrons`, [`Al<sup>3+</sup> + e<sup>&minus;</sup> &rarr; Al<sup>2+</sup>, with 1 electron`, `Al &rarr; Al<sup>3+</sup> + 3e<sup>&minus;</sup>, with 3 electrons`, `2Al<sup>3+</sup> + 6e<sup>&minus;</sup> &rarr; Al<sub>2</sub>, with 6 electrons`], `<p>The cathode reduces Al<sup>3+</sup> to liquid aluminium, which sinks to the bottom of the cell (it is denser than the melt), taking 3 e<sup>&minus;</sup> per atom.</p>`),
  PN(4, 'Hall&ndash;H&eacute;roult', 'p3', `Find the mass in kg of the carbon anode burnt in making 1.08 kg of aluminium, if all the anode gas is CO<sub>2</sub>.`, 0.36, 0.01, 'kg', `<p>1.08 kg Al = 40 mol. From 2Al<sub>2</sub>O<sub>3</sub> + 3C &rarr; 4Al + 3CO<sub>2</sub>: C = 40 &times; 3/4 = 30 mol = 0.36 kg.</p>`, undefined, () => 40 * 0.75 * 12 / 1000),
];

const HAND5B = [
  nat(5, 'mixed: Faraday', `A copper refining cell and a Hall&ndash;H&eacute;roult cell carry the same charge in series. If 6.35 g of copper is deposited in the first, what mass of aluminium, in g, is formed in the second? (Cu = 63.5, Al = 27)`, 1.8, 0.02, 'g', `<p>Cu: 6.35/63.5 = 0.1 mol, two electrons each, so 0.2 mol of electrons passed.</p><p>Al needs 3 electrons per atom: 0.2/3 = 0.0667 mol &times; 27 = <b>1.8 g</b>.</p>`, `Different numbers of electrons per atom: 2 for Cu, 3 for Al.`, () => 6.35 / 63.5 * 2 / 3 * 27),
  nat(5, 'mixed: thermodynamics', `For MO + C &rarr; M + CO at 1273 K, &Delta;G&deg; = &minus;25 kJ per mole. Find the equilibrium constant K (take R = 8.314 J K<sup>&minus;1</sup> mol<sup>&minus;1</sup>), to one decimal.`, 10.6, 0.2, '', `<p>&Delta;G&deg; = &minus;RT ln K, so ln K = 25000/(8.314 &times; 1273) = 2.362.</p><p>K = e<sup>2.362</sup> = <b>10.6</b>.</p>`, `Use joules with R, not kilojoules.`, () => Math.exp(25000 / (8.314 * 1273))),
  mk(5, 'Ellingham', `Two oxide lines are &Delta;G&deg;(A) = &minus;800 + 0.2T and &Delta;G&deg;(B) = &minus;1100 + 0.4T (kJ per mole O<sub>2</sub>). For T above their crossing point, which statement is right?`, `The metal A can reduce the oxide of B, since the A line is the lower one`, [`The metal B can reduce the oxide of A`, `Neither can reduce the other above the crossing point`, `The oxide of A decomposes spontaneously on heating alone`], `<p>The lines cross where &minus;800 + 0.2T = &minus;1100 + 0.4T, so T = 1500 K. Above it, line B = &minus;1100 + 0.4T is higher than line A. At 2000 K: A = &minus;400, B = &minus;300. Metal A forms the more stable oxide, so it reduces BO.</p>`, `Which line is lower flips at the crossing point.`),
  nat(5, 'mixed: coordination', `Using the effective atomic number rule, find the total number of electrons around nickel (Z = 28) in Ni(CO)<sub>4</sub>.`, 36, 0, '', `<p>Ni(0) has 28 electrons. Each CO donates 2: 4 &times; 2 = 8.</p><p>EAN = 28 + 8 = <b>36</b>, the electron count of krypton. This is why Ni(CO)<sub>4</sub> is stable.</p>`, `Ni is in the zero state, so no electrons are lost.`, () => 28 + 8),
  nat(5, 'mixed: energy', `A cell works at 4.5 V. Find the electrical energy in kWh used to make 1 kg of aluminium at 100% current efficiency. (Al = 27, 1 F = 96500 C)`, 13.4, 0.1, 'kWh', `<p>1 kg = 37.04 mol Al. Charge = 37.04 &times; 3 &times; 96500 = 1.072 &times; 10<sup>7</sup> C.</p><p>Energy = QV = 1.072 &times; 10<sup>7</sup> &times; 4.5 = 4.825 &times; 10<sup>7</sup> J. Divide by 3.6 &times; 10<sup>6</sup> J per kWh: <b>13.4 kWh</b>.</p>`, `1 kWh = 3.6 million joules.`, () => 1000 / 27 * 289500 * 4.5 / 3.6e6),
  msq(5, 'electrolytic refining of copper', `In the electrolytic refining of copper, which statements are correct?`, [`The cathode is a thin sheet of pure copper`, `The electrolyte is acidified copper sulphate`, `Ag and Au fall as anode mud`, `Zinc impurity in the anode deposits on the cathode along with copper`], [0, 1, 2], `<p>Zinc is oxidised at the anode but stays as Zn<sup>2+</sup> in solution, since E&deg;(Zn<sup>2+</sup>/Zn) = &minus;0.76 V is far below E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V. Cu<sup>2+</sup> is reduced first at the low voltage used, so zinc is not deposited.</p>`, `Dissolving at the anode and depositing at the cathode are two different tests.`),
  mk(4, 'decomposition of oxides', `Which oxide is the easiest to decompose by heating alone, to give the metal?`, `HgO`, [`ZnO`, `Al<sub>2</sub>O<sub>3</sub>`, `Fe<sub>2</sub>O<sub>3</sub>`], `<p>HgO is at the top of the Ellingham diagram: its &Delta;G&deg; of formation becomes positive at about 700 K, so it decomposes to Hg + O<sub>2</sub>. Zn, Al and Fe oxides remain stable at much higher temperatures.</p>`),
  mk(5, 'mixed: electrochemistry', `Why is zinc, present as an impurity in an impure copper anode, not deposited at the cathode of the refining cell?`, `Zn<sup>2+</sup> is reduced only at a much more negative potential, so Cu<sup>2+</sup> is reduced first`, [`Zinc does not dissolve at the anode`, `Zinc forms an insoluble sulphate on the anode`, `Zinc is a gas at the cell temperature`], `<p>E&deg;(Zn<sup>2+</sup>/Zn) = &minus;0.76 V; E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V. The cell voltage is just enough to reduce Cu<sup>2+</sup>. Zinc does dissolve at the anode, since it oxidises more easily than copper, and builds up in the electrolyte as Zn<sup>2+</sup>.</p>`, `Zinc does dissolve; it is the deposit that does not occur.`),
  nat(5, 'matte treatment', `Matte contains 880 g of FeS, which is converted by 2FeS + 3O<sub>2</sub> &rarr; 2FeO + 2SO<sub>2</sub> and then FeO + SiO<sub>2</sub> &rarr; FeSiO<sub>3</sub>. What mass of silica, in g, is needed? (Fe = 56, S = 32, Si = 28, O = 16)`, 600, 0, 'g', `<p>FeS = 88 g/mol, so 880 g = 10 mol. Each FeS gives one FeO, and each FeO takes one SiO<sub>2</sub> (60 g/mol).</p><p>SiO<sub>2</sub> = 10 &times; 60 = <b>600 g</b>.</p>`, undefined, () => 10 * 60),
];

const FIXED = [...H1, ...HAND5B, ...H2, ...H3, ...H4, ...HAND5, ...HAND_NAT, ...HAND_MSQ, ...ASR, ...STM, ...MATCH, ...PASSAGES];

// ---------------- templates ----------------
const ORES = [['haematite', 'iron'], ['magnetite', 'iron'], ['siderite', 'iron'], ['bauxite', 'aluminium'], ['zinc blende', 'zinc'], ['calamine', 'zinc'], ['galena', 'lead'], ['cinnabar', 'mercury'], ['cassiterite', 'tin'], ['argentite', 'silver'], ['copper pyrites', 'copper'], ['malachite', 'copper'], ['cuprite', 'copper'], ['carnallite', 'magnesium'], ['pyrolusite', 'manganese'], ['chromite', 'chromium'], ['rutile', 'titanium'], ['wolframite', 'tungsten']];
const METALS = ['iron', 'aluminium', 'zinc', 'lead', 'mercury', 'tin', 'silver', 'copper', 'magnesium', 'manganese', 'chromium', 'titanium', 'tungsten', 'nickel', 'gold'];
const CONC = [['zinc blende', 'froth flotation'], ['galena', 'froth flotation'], ['copper pyrites', 'froth flotation'], ['haematite', 'hydraulic washing (gravity separation)'], ['bauxite', 'leaching with hot NaOH solution'], ['argentite', 'leaching with dilute NaCN solution in air'], ['native gold in quartz', 'leaching with dilute NaCN solution in air'], ['cassiterite with wolframite', 'magnetic separation']];
const CONC_ALL = ['froth flotation', 'hydraulic washing (gravity separation)', 'leaching with hot NaOH solution', 'leaching with dilute NaCN solution in air', 'magnetic separation'];
const REFINE = [['zinc', 'distillation'], ['mercury', 'distillation'], ['tin', 'liquation'], ['nickel', 'vapour phase refining (Mond process)'], ['zirconium', 'vapour phase refining (van Arkel method)'], ['germanium', 'zone refining'], ['silicon of semiconductor grade', 'zone refining'], ['blister copper (for high purity)', 'electrolytic refining'], ['silver containing lead', 'cupellation'], ['copper with a little Cu<sub>2</sub>O', 'poling']];
const REF_ALL = ['distillation', 'liquation', 'vapour phase refining (Mond process)', 'vapour phase refining (van Arkel method)', 'zone refining', 'electrolytic refining', 'cupellation', 'poling'];
const OXIDES = [['Fe<sub>2</sub>O<sub>3</sub>', 'Fe<sub>2</sub>O<sub>3</sub> + 2Al &rarr; Al<sub>2</sub>O<sub>3</sub> + 2Fe', 160, 2, 54], ['Cr<sub>2</sub>O<sub>3</sub>', 'Cr<sub>2</sub>O<sub>3</sub> + 2Al &rarr; Al<sub>2</sub>O<sub>3</sub> + 2Cr', 152, 2, 54], ['MnO<sub>2</sub>', '3MnO<sub>2</sub> + 4Al &rarr; 2Al<sub>2</sub>O<sub>3</sub> + 3Mn', 87, 4 / 3, 36]];
const CARB = [['CaCO<sub>3</sub>', 'CaO', 100, 56, 44], ['MgCO<sub>3</sub>', 'MgO', 84, 40, 44], ['ZnCO<sub>3</sub>', 'ZnO', 125, 81, 44], ['FeCO<sub>3</sub>', 'FeO', 116, 72, 44]];
const SULPH = [['ZnS', 97, 1, 'zinc blende'], ['PbS', 239, 1, 'galena'], ['Cu<sub>2</sub>S', 159, 0.5, 'copper glance']];
const MINERALS = [['Fe<sub>3</sub>O<sub>4</sub>', 168, 232], ['Fe<sub>2</sub>O<sub>3</sub>', 112, 160], ['ZnS', 65, 97], ['PbS', 207, 239], ['Cu<sub>2</sub>S', 127, 159], ['Al<sub>2</sub>O<sub>3</sub>', 54, 102], ['FeCO<sub>3</sub>', 56, 116], ['SnO<sub>2</sub>', 119, 151]];

const GENS = [
  gx('mt-g01', 3, 'nat', 'Faraday and aluminium', (rng) => {
    const I = pick(rng, 1, 5, 1) * 10000, t = pick(rng, 1, 6, 1), eff = pick(rng, 80, 95, 5); const m = 27 * I * t * 3600 * eff / 100 / 289500 / 1000;
    return { q: `A Hall&ndash;H&eacute;roult cell passes ${I} A for ${t} hour${t > 1 ? 's' : ''} with a current efficiency of ${eff}%. Find the mass of aluminium formed, in kg (Al = 27, 1 F = 96500 C).`, answer: +m.toFixed(2), tol: Math.max(0.02, m * 0.005), unit: 'kg', I, t, eff,
      sol: `<p>Q = ${I} &times; ${t} &times; 3600 = ${fmt(I * t * 3600, 4)} C. Each Al needs 3 electrons, so mass at 100% = Q &times; 27/(3 &times; 96500) = ${fmt(I * t * 3600 * 27 / 289500 / 1000, 4)} kg.</p><p>At ${eff}%: <b>${m.toFixed(2)} kg</b>.</p>`, trap: 'Three electrons per aluminium atom.' };
  }, (p) => (I3(p)) ),
  gx('mt-g02', 3, 'nat', 'electrolytic refining of copper', (rng) => {
    const I = pick(rng, 2, 20, 2), t = pick(rng, 10, 90, 10); const m = 63.5 * I * t * 60 / 96500 / 2;
    return { q: `In the electrolytic refining of copper, a current of ${I} A passes for ${t} minutes. How many grams of copper are deposited at the cathode? (Cu = 63.5, 1 F = 96500 C)`, answer: +m.toFixed(2), tol: Math.max(0.02, m * 0.01), unit: 'g', I, t,
      sol: `<p>Q = ${I} &times; ${t} &times; 60 = ${I * t * 60} C. Moles of electrons = ${I * t * 60}/96500 = ${fmt(I * t * 60 / 96500, 4)}.</p><p>Cu<sup>2+</sup> + 2e<sup>&minus;</sup> &rarr; Cu, so the mass is ${fmt(I * t * 60 / 96500 / 2, 4)} &times; 63.5 = <b>${m.toFixed(2)} g</b>.</p>`, trap: 'Convert minutes to seconds; two electrons per Cu.' };
  }, (p) => p.I * p.t * 60 * 63.5 / 193000),
  gx('mt-g03', 3, 'nat', 'purity of ore', (rng) => {
    const w = pick(rng, 200, 2000, 100), pct = pick(rng, 50, 90, 5); const m = w * pct / 100 * 112 / 160;
    return { q: `A haematite sample of ${w} kg contains ${pct}% Fe<sub>2</sub>O<sub>3</sub> and the rest is gangue. How many kilograms of iron can be extracted from it, if the extraction is complete? (Fe = 56, O = 16)`, answer: +m.toFixed(2), tol: Math.max(0.05, m * 0.005), unit: 'kg', w, pct,
      sol: `<p>Fe<sub>2</sub>O<sub>3</sub> in the ore = ${w} &times; ${pct}/100 = ${w * pct / 100} kg. Iron makes up 112/160 = 0.7 of it.</p><p>Iron = ${w * pct / 100} &times; 0.7 = <b>${m.toFixed(2)} kg</b>.</p>`, trap: 'Use only the oxide in the ore.' };
  }, (p) => 0.7 * p.w * p.pct / 100),
  gx('mt-g04', 3, 'nat', 'temperature of switching', (rng) => {
    const H = pick(rng, 100, 400, 20), S = pick(rng, 100, 250, 10); const T = H * 1000 / S;
    return { q: `For a reduction, &Delta;H&deg; = +${H} kJ and &Delta;S&deg; = +${S} J K<sup>&minus;1</sup>. Above what temperature, in K, is the reduction spontaneous under standard conditions? (Assume &Delta;H&deg; and &Delta;S&deg; stay constant.)`, answer: +T.toFixed(1), tol: Math.max(0.5, T * 0.005), unit: 'K', H, S,
      sol: `<p>&Delta;G&deg; = &Delta;H&deg; &minus; T&Delta;S&deg; &lt; 0 when T &gt; &Delta;H&deg;/&Delta;S&deg;.</p><p>T = ${H * 1000}/${S} = <b>${T.toFixed(1)} K</b>.</p>`, trap: 'kJ against J.' };
  }, (p) => p.H * 1000 / p.S),
  gx('mt-g05', 4, 'nat', 'coupled reactions', (rng) => {
    const a = pick(rng, 300, 500, 10), b = pick(rng, 200, 450, 10); const d = (-a + b) / 2;
    return { q: `At a certain temperature, &Delta;G&deg; for 2C + O<sub>2</sub> &rarr; 2CO is &minus;${a} kJ and for 2M + O<sub>2</sub> &rarr; 2MO is &minus;${b} kJ. Find &Delta;G&deg; in kJ for MO + C &rarr; M + CO, per mole of MO.`, answer: d, tol: 0.01, unit: 'kJ', a, b,
      sol: `<p>Subtract the second equation from the first: 2MO + 2C &rarr; 2M + 2CO, &Delta;G&deg; = &minus;${a} &minus; (&minus;${b}) = ${-a + b} kJ.</p><p>For one mole of MO: <b>${d} kJ</b> (${d < 0 ? 'spontaneous' : 'not spontaneous'}).</p>`, trap: 'Halve the value because the equation has two moles of MO.' };
  }, (p) => (p.b - p.a) / 2),
  gx('mt-g06', 3, 'nat', 'roasting of sulphides', (rng) => {
    const [f, M, k, nm] = choose(rng, SULPH); const n = pick(rng, 1, 6, 1); const w = n * M; const v = n * (f === 'Cu<sub>2</sub>S' ? 1 : 1) * 22.4;
    return { q: `${w} g of ${nm} (${f}) is roasted fully in air (the sulphur ends as SO<sub>2</sub>). Find the volume of SO<sub>2</sub> at STP in litres (Zn = 65, Pb = 207, Cu = 63.5, S = 32; molar volume 22.4 L).`, answer: +v.toFixed(1), tol: Math.max(0.2, v * 0.005), unit: 'L', n,
      sol: `<p>Molar mass of ${f} = ${M}, so moles = ${w}/${M} = ${n}.</p><p>Each formula unit has one sulphur, so ${n} mol of SO<sub>2</sub>. Volume = ${n} &times; 22.4 = <b>${v.toFixed(1)} L</b>.</p>`, trap: 'Count sulphur atoms per formula unit.' };
  }, (p) => p.n * 22.4),
  gx('mt-g07', 3, 'nat', 'CO needed in the blast furnace', (rng) => {
    const o = choose(rng, [['Fe<sub>2</sub>O<sub>3</sub>', 160, 3], ['Fe<sub>3</sub>O<sub>4</sub>', 232, 4], ['FeO', 72, 1]]); const n = pick(rng, 1, 5, 1); const m = n * o[1];
    return { q: `How many moles of CO are needed to reduce ${m} g of ${o[0]} completely to iron? (Fe = 56, O = 16)`, answer: n * o[2], tol: 0, unit: 'mol', n, k: o[2],
      sol: `<p>Moles of ${o[0]} = ${m}/${o[1]} = ${n}. Each oxygen atom removed needs one CO, and each formula unit has ${o[2]} oxygen atoms.</p><p>CO = ${n} &times; ${o[2]} = <b>${n * o[2]} mol</b>.</p>`, trap: 'One CO per oxygen atom, not per formula unit.' };
  }, (p) => p.n * p.k),
  gx('mt-g08', 3, 'nat', 'thermite', (rng) => {
    const [f, eq, M, ratio, am] = choose(rng, OXIDES); const n = pick(rng, 1, 5, 1); const w = n * M; const al = n * ratio * 27;
    return { q: `How many grams of aluminium are needed to reduce ${w} g of ${f} in the thermite process? (Fe = 56, Cr = 52, Mn = 55, O = 16, Al = 27)`, answer: +al.toFixed(1), tol: 0.2, unit: 'g', n, ratio,
      sol: `<p>${eq}.</p><p>Moles of oxide = ${w}/${M} = ${n}. Al needed per mole of oxide = ${fmt(ratio, 3)} mol, so Al = ${n} &times; ${fmt(ratio, 3)} &times; 27 = <b>${al.toFixed(1)} g</b>.</p>`, trap: 'Balance the equation first.' };
  }, (p) => p.n * p.ratio * 27),
  gx('mt-g09', 3, 'nat', 'calcination', (rng) => {
    const [f, ox, M, Mo, Mc] = choose(rng, CARB); const n = pick(rng, 1, 5, 1) / 2; const w = n * M; const res = n * Mo;
    return { q: `${fmt(w, 4)} g of pure ${f} is calcined completely. Find the mass of solid ${ox.replace(/(\d)/g, '<sub>$1</sub>')} left, in grams (Ca = 40, Mg = 24, Zn = 65, Fe = 56, C = 12, O = 16).`, answer: +res.toFixed(2), tol: Math.max(0.02, res * 0.005), unit: 'g', n, Mo,
      sol: `<p>${f} &rarr; ${ox.replace(/(\d)/g, '<sub>$1</sub>')} + CO<sub>2</sub>. Molar mass of ${f} = ${M}, so moles = ${fmt(w, 4)}/${M} = ${n}.</p><p>One mole of oxide per mole of carbonate (molar mass ${Mo}): ${n} &times; ${Mo} = <b>${res.toFixed(2)} g</b>.</p>`, trap: 'The solid left is the oxide, not the lost CO<sub>2</sub>.' };
  }, (p) => p.n * p.Mo),
  gx('mt-g10', 2, 'nat', 'percentage of metal in a mineral', (rng) => {
    const [f, m, M] = choose(rng, MINERALS); const a = m / M * 100;
    return { q: `Find the percentage by mass of the metal in ${f} (Fe = 56, Zn = 65, Pb = 207, Cu = 63.5, Al = 27, Sn = 119, S = 32, C = 12, O = 16).`, answer: +a.toFixed(2), tol: 0.05, unit: '%', m, M,
      sol: `<p>Molar mass = ${M} g/mol. The metal in one formula unit has mass ${m}.</p><p>% = ${m}/${M} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>`, trap: 'Count all metal atoms in the formula.' };
  }, (p) => p.m * 100 / p.M),
  gx('mt-g11', 1, 'mcq', 'ores and their metals', (rng) => {
    const [o, m] = choose(rng, ORES); const w = METALS.filter((x) => x !== m); const ws = []; while (ws.length < 3) { const c = choose(rng, w); if (!ws.includes(c)) ws.push(c); }
    const { options, answer } = shuffleOpts(rng, m, ws);
    return { q: `${o[0].toUpperCase() + o.slice(1)} is an important ore of which metal?`, options, answer, m,
      sol: `<p>${o[0].toUpperCase() + o.slice(1)} is a mineral of <b>${m}</b>.</p>`, trap: 'Learn each ore with its formula and its metal.' };
  }, (p) => p.options.indexOf(p.m)),
  gx('mt-g12', 2, 'mcq', 'concentration of ores', (rng) => {
    const [o, m] = choose(rng, CONC); const ws = CONC_ALL.filter((x) => x !== m);
    const { options, answer } = shuffleOpts(rng, m, ws.slice(0, 3));
    return { q: `The usual method of concentrating ${o} is`, options, answer, m,
      sol: `<p>${o[0].toUpperCase() + o.slice(1)} is concentrated by <b>${m}</b>. Sulphides rise in the froth; heavy oxides are washed; Al<sub>2</sub>O<sub>3</sub> and the noble metals dissolve in a suitable leachant; a magnet separates a magnetic ore.</p>`, trap: 'Choose by the type of ore: sulphide, oxide, amphoteric oxide or native.' };
  }, (p) => p.options.indexOf(p.m)),
  gx('mt-g13', 2, 'mcq', 'refining methods', (rng) => {
    const [o, m] = choose(rng, REFINE); const ws = REF_ALL.filter((x) => x !== m); const sh = [...ws].sort(() => rng() - 0.5).slice(0, 3);
    const { options, answer } = shuffleOpts(rng, m, sh);
    return { q: `The best method to refine ${o} is`, options, answer, m,
      sol: `<p>${o[0].toUpperCase() + o.slice(1)} is refined by <b>${m}</b>.</p>`, trap: 'Know one metal for each refining method.' };
  }, (p) => p.options.indexOf(p.m)),
  gx('mt-g14', 3, 'nat', 'faradays for aluminium', (rng) => {
    const w = pick(rng, 27, 270, 27); const f = w / 27 * 3;
    return { q: `How many faradays of electricity are needed to make ${w} g of aluminium from Al<sup>3+</sup> in the cell? (Al = 27)`, answer: f, tol: 0, unit: 'F', w,
      sol: `<p>Moles of Al = ${w}/27 = ${w / 27}. Three electrons per Al: ${w / 27} &times; 3 = <b>${f} F</b>.</p>` };
  }, (p) => p.w / 9),
  gx('mt-g15', 3, 'nat', 'limestone flux', (rng) => {
    const n = pick(rng, 1, 8, 1); const w = n * 60; const c = n * 100;
    return { q: `A charge contains ${w} kg of SiO<sub>2</sub> as gangue. What mass of CaCO<sub>3</sub> in kg is needed to turn all of it into CaSiO<sub>3</sub> slag? (Ca = 40, Si = 28, O = 16, C = 12)`, answer: c, tol: 0, unit: 'kg', n,
      sol: `<p>CaCO<sub>3</sub> &rarr; CaO + CO<sub>2</sub>, CaO + SiO<sub>2</sub> &rarr; CaSiO<sub>3</sub>. SiO<sub>2</sub> = 60 kg per kmol, so ${w}/60 = ${n} kmol.</p><p>One CaCO<sub>3</sub> per SiO<sub>2</sub>: ${n} &times; 100 = <b>${c} kg</b>.</p>` };
  }, (p) => p.n * 100),
];
function I3(p) { return +(27 * p.I * p.t * 3600 * p.eff / 100 / 289500 / 1000).toFixed(2); }

export default {
  topic: 'metallurgy',
  groups: GRP,
  items: FIXED,
  gens: GENS,
};
